const epKey='aozEmpressPlanner_v1';
const epKeys={damage_percent:10,biotroop_attack_defense_health_percent:11,troop_and_biotroop_health_defense_percent:12,all_troop_attack_percent:13,additional_biotroop_attack_percent:14,additional_defense_health_percent:15,self_defense:16,self_health_display:17};
let epStage=0,epFilter='all',epBudget='',epSaved=true;
const epState=Object.fromEntries(etData.map((t,i)=>[t.id,{a:1,b:20,sa:0,sb:0,open:i===0}]));
function epInt(v){return Number.isInteger(v)&&v>=1&&v<=20}
function epLoad(){try{const stored=JSON.parse(localStorage.getItem(epKey)||'null');if(!stored)return;for(const t of etData){const v=stored.talents?.[t.id];if(v&&epInt(v.a)&&epInt(v.b)&&v.b>=v.a){epState[t.id].a=v.a;epState[t.id].b=v.b;const st=epState[t.id];if(t.star_costs){st.sa=Math.max(0,Math.min(15,st.a-5,Number.isInteger(v.sa)?v.sa:0));st.sb=Math.max(st.sa,Math.min(15,st.b-5,Number.isInteger(v.sb)?v.sb:0))}}}if(typeof stored.budget==='string'&&/^\d{0,12}$/.test(stored.budget))epBudget=stored.budget;if(Number.isInteger(stored.stage)&&stored.stage>=0&&stored.stage<=5)epStage=stored.stage===4&&!stored.stageV2?5:stored.stage;if(['all','attack','defense'].includes(stored.filter))epFilter=stored.filter}catch{epSaved=false}}
function epSave(){try{const talents=Object.fromEntries(Object.entries(epState).map(([id,s])=>[id,{a:s.a,b:s.b,sa:s.sa,sb:s.sb}]));localStorage.setItem(epKey,JSON.stringify({talents,budget:epBudget,stage:epStage,stageV2:true,filter:epFilter}));epSaved=true}catch{epSaved=false}}
epLoad();
function epCost(t,a,b){return t.levels[b-1].cumulative_resource_from_level_1-t.levels[a-1].cumulative_resource_from_level_1}
function epResources(t,a,b,sa=0,sb=0){const x=t.levels[a-1],y=t.levels[b-1];return [epCost(t,a,b),y.cumulative_skeleton-x.cumulative_skeleton,y.cumulative_fission-x.cumulative_fission,t.star_costs?t.star_costs.slice(sa,sb).reduce((n,x)=>n+x,0):0]}
function epAllResources(){return etData.reduce((sum,t)=>{const st=epState[t.id];return epResources(t,st.a,st.b,st.sa,st.sb).map((v,i)=>sum[i]+v)},[0,0,0,0])}
function epTotal(){return etData.reduce((sum,t)=>{const s=epState[t.id];return sum+epCost(t,s.a,s.b)},0)}
function epAffordable(t){const s=epState[t.id];if(epBudget==='')return s.b;const available=Number(epBudget)-(epTotal()-epCost(t,s.a,s.b));let result=s.a;for(let n=s.a;n<=20;n++){if(epCost(t,s.a,n)<=available)result=n;else break}return result}
function epNode(tag,cls,txt){const el=document.createElement(tag);if(cls)el.className=cls;if(txt!==undefined)el.textContent=txt;return el}
function epFmt(k,v){return typeof v==='number'?fmt(v)+(k.endsWith('_percent')?'%':''):v}
function epButton(cls,txt,fn){const b=epNode('button',cls,txt);b.type='button';b.onclick=fn;return b}
function epToggle(btn,active){btn.setAttribute('aria-pressed',String(active))}
