function msSum(a,x,y){return a.slice(x,y).reduce((s,n)=>s+n,0)}
function msCosts(mode,i,r){const [a,b,s=0,t=0]=r;if(mode==='evolution'){const out=[0,0,0,0];for(let j=a;j<b;j++)msEvoCost[Math.min(4,Math.floor(j/10))].forEach((v,k)=>out[k]+=v);return out}if(mode==='talents'){const talent=etData[msExactTalentMap[i]];return epResources(talent,a,b,s,t)}if(mode==='equipment')return [msSum(msGear[Math.floor(i/4)],a-1,b-1)];if(mode==='awakening')return [msSum(msAwake[i],a,b)];return [msSum(msSkin,a+1,b+1)]}

